+            {
+                int corners = 0;
+                bool orthogonal = true;
+                XYZ lastDir = XYZ.Zero;
+                XYZ firstValidDir = XYZ.Zero;
+                
+                for (int i = 0; i < pts.Count - 1; i++)
+                {
+                    var p1 = currentTransform.OfPoint(pts[i]);
+                    var p2 = currentTransform.OfPoint(pts[i + 1]);
